def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals)
    merged = []

    for current in sorted_intervals:
        if not merged or current[0] > merged[-1][1]:
            merged.append([current[0], current[1]])
        else:
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged
```
